"use strict";

// Execute the generated, standalone player-facing page against a tiny DOM.
// This checks the actual render function: a withdrawn card must replace, not
// merely visually cover, its prior action and rationale. The fixture is
// generated by the public CLI and contains no game image or private account.

const assert = require("node:assert/strict");
const childProcess = require("node:child_process");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const test = require("node:test");
const vm = require("node:vm");

const project = path.resolve(__dirname, "../../..");
const python = path.join(project, ".venv", "bin", "python");

function node() {
  return {
    textContent: "", className: "", disabled: false, children: [], onclick: null,
    append(...items) { this.children.push(...items); },
    replaceChildren(...items) { this.children = [...items]; this.textContent = ""; },
  };
}

function visibleText(value) {
  return [value.textContent, ...value.children.flatMap(visibleText)].join(" ");
}

function generatedPage() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "jcc-human-coach-test-"));
  fs.chmodSync(root, 0o700);
  const destination = path.join(root, "demo");
  const run = childProcess.spawnSync(python, ["-B", "-m", "jcc_human_coach", "--demo-output", destination], {
    cwd: project,
    env: { ...process.env, PYTHONPATH: path.join(project, "src") },
    encoding: "utf8",
  });
  assert.equal(run.status, 0, run.stderr || run.stdout);
  return {root, source: fs.readFileSync(path.join(destination, "player-coach-demo.html"), "utf8")};
}

function page(source) {
  const ids = new Map();
  const get = (id) => {
    if (!ids.has(id)) ids.set(id, node());
    return ids.get(id);
  };
  const document = { querySelector: (selector) => get(selector), createElement: () => node() };
  const script = source.match(/<script>([\s\S]*)<\/script>/);
  assert.ok(script, "generated page must include its local renderer");
  vm.runInNewContext(script[1], {
    document, performance: { now: () => 100 }, clearInterval() {}, clearTimeout() {},
    setInterval() { return 1; }, setTimeout() { return 2; }, Math,
  });
  return { state: get("#state"), previous: get("#previous"), next: get("#next") };
}

test("refresh replaces old cards and withdrawal has no stale player action", () => {
  const generated = generatedPage();
  try {
    const p = page(generated.source);
    assert.match(visibleText(p.state), /虚构例子 · 站位检查/);
    p.next.onclick();
    assert.match(visibleText(p.state), /虚构可用单位/);
    assert.doesNotMatch(visibleText(p.state), /前后排位置/);
    p.next.onclick();
    assert.match(visibleText(p.state), /虚构羁绊甲/);
    p.next.onclick();
    assert.match(visibleText(p.state), /巨人杀手/);
    p.next.onclick();
    assert.match(visibleText(p.state), /阵容转型缺口/);
    p.next.onclick();
    assert.match(visibleText(p.state), /提示已撤回/);
    assert.doesNotMatch(visibleText(p.state), /阵容转型/);
    assert.doesNotMatch(visibleText(p.state), /金币代价/);
  } finally {
    fs.rmSync(generated.root, {recursive: true, force: true});
  }
});
